//! The recipe book between a 1.12.2 client and a 1.13 backend.
//!
//! 1.12.2 numbers recipes, 1.13 names them. `data/down_recipes.json`
//! (generated by `data/down_recipes.py` from both server jars) lists the
//! 1.12.2 recipes in ID order and the 1.13 names of those 1.13 renamed.
//! Recipes 1.12.2 lacks (smelting, which joined the recipe book in 1.13,
//! and new blocks) are left out of what the client is told.
//!
//! A backend behind later steps may name recipes 1.13 never had: from
//! 1.21.2 the protocol carries no recipe names and the 1.21.1 step makes
//! up `rift:recipe/<n>`, and plugins add their own. Such a crafting recipe
//! stands for the 1.12.2 recipes that make the same item
//! (`data/down_recipe_results.json`, generated by
//! `data/down_recipe_results.py` from the 1.13 server jar), learnt from the
//! recipe list the backend declares, and the client's clicks on those go
//! back under the backend's name.
use super::{Down, NEWER};
use crate::{
    Packet, State,
    codec::item::recipes::{RecipeData, UpdateRecipes},
    data,
    step::Cx,
    wire::{Reader, Writer, invalid},
};
use serde::Deserialize;
use std::{
    collections::{BTreeSet, HashMap},
    io,
    sync::OnceLock,
};

#[derive(Deserialize)]
struct Raw {
    ids: Vec<String>,
    /// 1.13 name to 1.12.2 name.
    renames: HashMap<String, String>,
}

/// Recipe IDs both ways.
pub(super) struct Recipes {
    /// The 1.13 name of each 1.12.2 recipe ID.
    names: Vec<String>,
    /// The 1.12.2 ID of each 1.13 name that has one.
    ids: HashMap<String, i32>,
    /// The 1.12.2 crafting recipes that make each item (1.13 name without
    /// namespace).
    by_result: HashMap<String, Vec<i32>>,
}

/// What the backend declared under names 1.12.2 does not number.
#[derive(Default)]
pub(super) struct Declared {
    /// The 1.12.2 recipes each such crafting recipe stands for.
    stands_for: HashMap<String, Vec<i32>>,
    /// The backend's name for each 1.12.2 recipe it declared differently.
    names: HashMap<i32, String>,
}

impl Recipes {
    pub(super) fn get() -> &'static Self {
        static RECIPES: OnceLock<Recipes> = OnceLock::new();
        RECIPES.get_or_init(|| {
            let raw: Raw = serde_json::from_str(include_str!("../data/down_recipes.json"))
                .expect("down_recipes.json is valid");
            let legacy: HashMap<&str, &str> = raw
                .renames
                .iter()
                .map(|(modern, legacy)| (legacy.as_str(), modern.as_str()))
                .collect();
            let names: Vec<String> = raw
                .ids
                .iter()
                .map(|name| {
                    legacy
                        .get(name.as_str())
                        .copied()
                        .unwrap_or(name)
                        .to_owned()
                })
                .collect();
            let ids: HashMap<String, i32> = names
                .iter()
                .enumerate()
                .map(|(id, name)| (name.clone(), id as i32))
                .collect();
            let results: HashMap<String, String> =
                serde_json::from_str(include_str!("../data/down_recipe_results.json"))
                    .expect("down_recipe_results.json is valid");
            let mut by_result: HashMap<String, Vec<i32>> = HashMap::new();
            for (name, result) in results {
                if let Some(&id) = ids.get(&name) {
                    by_result
                        .entry(data::strip(&result).to_owned())
                        .or_default()
                        .push(id);
                }
            }
            for list in by_result.values_mut() {
                list.sort_unstable();
            }
            Recipes {
                names,
                ids,
                by_result,
            }
        })
    }

    /// The 1.12.2 ID of a 1.13 recipe name, with or without namespace.
    pub(super) fn id(&self, name: &str) -> Option<i32> {
        self.ids
            .get(name.strip_prefix("minecraft:").unwrap_or(name))
            .copied()
    }

    /// The 1.13 name (namespaced) of a 1.12.2 recipe ID.
    pub(super) fn name(&self, id: i32) -> Option<String> {
        let name = self.names.get(usize::try_from(id).ok()?)?;
        Some(format!("minecraft:{name}"))
    }
}

impl Declared {
    /// Learn the crafting recipes of a 1.13 `update_recipes` whose names
    /// 1.12.2 does not number. Each list replaces the previous one.
    fn learn(&mut self, packet: &[u8]) -> io::Result<()> {
        let mut reader = Reader::new(packet);
        let UpdateRecipes::Recipes(list) = UpdateRecipes::read(NEWER, &mut reader)? else {
            return Err(invalid("recipe displays in a 1.13 recipe list"));
        };
        reader.finish()?;
        let recipes = Recipes::get();
        let items = data::version(NEWER).expect_registry("item");
        *self = Self::default();
        for recipe in list {
            if recipes.id(&recipe.id).is_some() {
                continue;
            }
            let (RecipeData::Shaped { result, .. } | RecipeData::Shapeless { result, .. }) =
                &recipe.data
            else {
                continue;
            };
            let Some(item) = result.as_ref().and_then(|stack| items.name(stack.id)) else {
                continue;
            };
            let Some(ids) = recipes.by_result.get(item) else {
                continue;
            };
            for &id in ids {
                self.names.entry(id).or_insert_with(|| recipe.id.clone());
            }
            self.stands_for.insert(recipe.id, ids.clone());
        }
        Ok(())
    }

    /// The 1.12.2 IDs a 1.13 recipe name stands for.
    fn ids(&self, name: &str) -> Vec<i32> {
        match Recipes::get().id(name) {
            Some(id) => vec![id],
            None => self.stands_for.get(name).cloned().unwrap_or_default(),
        }
    }

    /// The name the backend knows a 1.12.2 recipe ID by.
    fn name(&self, id: i32) -> Option<String> {
        match self.names.get(&id) {
            Some(name) => Some(name.clone()),
            None => Recipes::get().name(id),
        }
    }

    /// Read a list of 1.13 recipe names, keeping those 1.12.2 has.
    fn read_names(&self, reader: &mut Reader<'_>) -> io::Result<Vec<i32>> {
        let mut ids = BTreeSet::new();
        let mut ordered = Vec::new();
        for _ in 0..reader.count()? {
            for id in self.ids(reader.string(32767)?) {
                if ids.insert(id) {
                    ordered.push(id);
                }
            }
        }
        Ok(ordered)
    }
}

fn write_ids(writer: &mut Writer, ids: &[i32]) {
    writer.varint(ids.len() as i32);
    for id in ids {
        writer.varint(*id);
    }
}

impl Down {
    /// The backend's recipe definitions: 1.12.2 has them built in, so they
    /// are only read for the names it does not number, and dropped. A list
    /// this step cannot read leaves those names unknown.
    pub(super) fn update_recipes(
        &mut self,
        _cx: &mut Cx<'_>,
        _state: State,
        packet: Packet,
    ) -> io::Result<()> {
        if self.declared.learn(&packet.data).is_err() {
            self.declared = Declared::default();
        }
        Ok(())
    }

    /// Unlocked recipes: 1.13 adds the furnace book's state and names the
    /// recipes. Action 0 (the list sent on joining) carries the recipes
    /// to show as new a second time.
    pub(super) fn recipe(
        &mut self,
        cx: &mut Cx<'_>,
        state: State,
        packet: Packet,
    ) -> io::Result<()> {
        let mut reader = Reader::new(&packet.data);
        let action = reader.varint()?;
        if !(0..=2).contains(&action) {
            return Err(invalid("invalid recipe book action"));
        }
        let (crafting_open, crafting_filter) = (reader.bool()?, reader.bool()?);
        reader.bool()?;
        reader.bool()?;
        let recipes = self.declared.read_names(&mut reader)?;
        let highlighted = if action == 0 {
            Some(self.declared.read_names(&mut reader)?)
        } else {
            None
        };
        reader.finish()?;
        if action != 0 && recipes.is_empty() {
            return Ok(());
        }
        let mut out = Writer::new();
        out.varint(action).bool(crafting_open).bool(crafting_filter);
        write_ids(&mut out, &recipes);
        if let Some(highlighted) = highlighted {
            write_ids(&mut out, &highlighted);
        }
        cx.to_client(state, Packet::new(packet.id, out.into_inner()));
        Ok(())
    }

    /// The recipe the server shows as a ghost in the crafting grid.
    pub(super) fn place_ghost_recipe(
        &mut self,
        cx: &mut Cx<'_>,
        state: State,
        packet: Packet,
    ) -> io::Result<()> {
        let mut reader = Reader::new(&packet.data);
        let window = reader.i8()?;
        let name = reader.string(32767)?;
        reader.finish()?;
        let Some(&id) = self.declared.ids(name).first() else {
            return Ok(());
        };
        let mut out = Writer::new();
        out.i8(window).varint(id);
        cx.to_client(state, Packet::new(packet.id, out.into_inner()));
        Ok(())
    }

    /// A click on a recipe in the book.
    pub(super) fn place_recipe(
        &mut self,
        cx: &mut Cx<'_>,
        state: State,
        packet: Packet,
    ) -> io::Result<()> {
        let mut reader = Reader::new(&packet.data);
        let window = reader.i8()?;
        let id = reader.varint()?;
        let make_all = reader.bool()?;
        reader.finish()?;
        let Some(name) = self.declared.name(id) else {
            return Ok(());
        };
        let mut out = Writer::new();
        out.i8(window).string(&name).bool(make_all);
        cx.to_backend(state, Packet::new(packet.id, out.into_inner()));
        Ok(())
    }

    /// Type 0 marks a recipe as seen (by Int ID in 1.12.2), type 1 sends the
    /// crafting book's state, to which 1.13 adds the furnace book's. A 1.12
    /// client has no furnace book: it stays closed and unfiltered.
    pub(super) fn recipe_book_update(
        &mut self,
        cx: &mut Cx<'_>,
        state: State,
        packet: Packet,
    ) -> io::Result<()> {
        let mut reader = Reader::new(&packet.data);
        let kind = reader.varint()?;
        let mut out = Writer::new();
        out.varint(kind);
        match kind {
            0 => {
                let id = reader.i32()?;
                reader.finish()?;
                let Some(name) = self.declared.name(id) else {
                    return Ok(());
                };
                out.string(&name);
            }
            1 => {
                let (open, filter) = (reader.bool()?, reader.bool()?);
                reader.finish()?;
                out.bool(open).bool(filter).bool(false).bool(false);
            }
            _ => return Err(invalid("invalid recipe book update")),
        }
        cx.to_backend(state, Packet::new(packet.id, out.into_inner()));
        Ok(())
    }
}
